use super::*;

/// A Display P3 ICC profile generated by the CMS (no vendor file).
fn p3_icc() -> Vec<u8> {
    ColorProfile::new_display_p3().encode().expect("encode P3")
}

fn srgb_icc() -> Vec<u8> {
    ColorProfile::new_srgb().encode().expect("encode sRGB")
}

fn png_with(icc: Option<&[u8]>, srgb_chunk: bool) -> Vec<u8> {
    let mut info = png::Info::with_size(2, 1);
    info.color_type = png::ColorType::Rgba;
    info.bit_depth = png::BitDepth::Eight;
    if let Some(icc) = icc {
        info.icc_profile = Some(std::borrow::Cow::Owned(icc.to_vec()));
    }
    if srgb_chunk {
        info.srgb = Some(png::SrgbRenderingIntent::Perceptual);
    }
    let mut out = Vec::new();
    {
        let enc = png::Encoder::with_info(&mut out, info).unwrap();
        let mut w = enc.write_header().unwrap();
        w.write_image_data(&[255, 0, 0, 255, 0, 255, 0, 128])
            .unwrap();
        w.finish().unwrap();
    }
    out
}

/// Inserts a chunk right after IHDR (signature 8 + IHDR 25 bytes).
fn insert_chunk(png: &[u8], kind: [u8; 4], body: &[u8]) -> Vec<u8> {
    let mut chunk = Vec::new();
    chunk.extend_from_slice(&(body.len() as u32).to_be_bytes());
    chunk.extend_from_slice(&kind);
    chunk.extend_from_slice(body);
    let mut crc = flate2::Crc::new();
    crc.update(&kind);
    crc.update(body);
    chunk.extend_from_slice(&crc.sum().to_be_bytes());
    let mut out = png[..33].to_vec();
    out.extend_from_slice(&chunk);
    out.extend_from_slice(&png[33..]);
    out
}

/// JPEG markers only (enough for [`sniff`]): APP2 ICC split into two
/// segments, SOF0 with `components`, SOS.
fn jpeg_header(icc: Option<&[u8]>, components: u8) -> Vec<u8> {
    let mut out = vec![0xFF, 0xD8, 0xFF, 0xE0, 0, 4, 0, 0];
    if let Some(icc) = icc {
        let half = icc.len() / 2;
        for (i, part) in [&icc[..half], &icc[half..]].iter().enumerate().rev() {
            out.extend_from_slice(&[0xFF, 0xE2]);
            out.extend_from_slice(&((part.len() + 16) as u16).to_be_bytes());
            out.extend_from_slice(b"ICC_PROFILE\0");
            out.extend_from_slice(&[i as u8 + 1, 2]);
            out.extend_from_slice(part);
        }
    }
    let mut sof = vec![8, 0, 1, 0, 1, components];
    for c in 0..components {
        sof.extend_from_slice(&[c + 1, 0x11, 0]);
    }
    out.extend_from_slice(&[0xFF, 0xC0]);
    out.extend_from_slice(&((sof.len() + 2) as u16).to_be_bytes());
    out.extend_from_slice(&sof);
    out.extend_from_slice(&[0xFF, 0xDA, 0, 2, 0xFF, 0xD9]);
    out
}

fn srgb_decode(v: f64) -> f64 {
    if v <= 0.04045 {
        v / 12.92
    } else {
        ((v + 0.055) / 1.055).powf(2.4)
    }
}

fn srgb_encode(v: f64) -> f64 {
    let v = v.clamp(0.0, 1.0);
    if v <= 0.003_130_8 {
        v * 12.92
    } else {
        1.055 * v.powf(1.0 / 2.4) - 0.055
    }
}

/// Reference P3 → sRGB (both D65, same transfer curve) from the primaries'
/// matrix, clipped.
fn p3_to_srgb_reference(p: [u8; 3]) -> [u8; 3] {
    const M: [[f64; 3]; 3] = [
        [1.224_940_2, -0.224_940_2, 0.0],
        [-0.042_056_9, 1.042_056_9, 0.0],
        [-0.019_637_6, -0.078_636_1, 1.098_273_7],
    ];
    let lin = p.map(|v| srgb_decode(f64::from(v) / 255.0));
    let mut out = [0u8; 3];
    for (o, row) in out.iter_mut().zip(M) {
        let v = row[0] * lin[0] + row[1] * lin[1] + row[2] * lin[2];
        *o = (srgb_encode(v) * 255.0).round() as u8;
    }
    out
}

fn p3() -> ToSrgb {
    let tag = sniff_bytes(&png_with(Some(&p3_icc()), false));
    ToSrgb::new(&tag)
}

fn close(a: &[u8], b: &[u8], tol: u8) -> bool {
    a.iter().zip(b).all(|(x, y)| x.abs_diff(*y) <= tol)
}

#[test]
fn png_iccp_is_read() {
    let icc = p3_icc();
    let tag = sniff_bytes(&png_with(Some(&icc), false));
    assert_eq!(tag.kind, ImageKind::Png);
    assert_eq!(tag.icc.as_deref(), Some(&icc[..]));
    assert!(!tag.srgb && tag.error.is_none());
    let t = ToSrgb::new(&tag);
    assert!(!t.is_identity());
    assert_eq!(t.label(), "Display P3");
    assert_eq!(t.note(), None);
}

#[test]
fn untagged_and_srgb_are_identity() {
    let plain = sniff_bytes(&png_with(None, false));
    assert!(plain.is_untagged());
    assert!(ToSrgb::new(&plain).is_identity());
    let chunk = sniff_bytes(&png_with(None, true));
    assert!(chunk.srgb);
    let t = ToSrgb::new(&chunk);
    assert!(t.is_identity());
    assert_eq!(t.label(), "sRGB");
    // An embedded sRGB profile changes nothing either.
    let t = ToSrgb::new(&sniff_bytes(&png_with(Some(&srgb_icc()), false)));
    assert!(t.is_identity());
    assert_eq!(t.note(), None);
}

#[test]
fn p3_pixels_convert_to_srgb() {
    let t = p3();
    // Pure P3 red is outside sRGB: it clips to sRGB red.
    let mut px = vec![255, 0, 0, 255, 128, 128, 128, 255, 200, 100, 50, 77];
    t.rgba8(&mut px).unwrap();
    assert!(close(&px[0..3], &[255, 0, 0], 1), "{:?}", &px[0..3]);
    // Gray stays gray (same white point and curve).
    assert!(close(&px[4..7], &[128, 128, 128], 1), "{:?}", &px[4..7]);
    // A mid colour matches the matrix reference; alpha is kept.
    let want = p3_to_srgb_reference([200, 100, 50]);
    assert!(close(&px[8..11], &want, 2), "{:?} vs {want:?}", &px[8..11]);
    assert_eq!((px[3], px[7], px[11]), (255, 255, 77));
}

#[test]
fn p3_sixteen_bit() {
    let t = p3();
    let src: Vec<u16> = [200u16, 100, 50, 65535, 32896, 32896, 32896, 1000]
        .into_iter()
        .enumerate()
        .map(|(i, v)| if i < 3 { v * 257 } else { v })
        .collect();
    let out = t.rgba16_to_rgba8(&src).unwrap();
    let want = p3_to_srgb_reference([200, 100, 50]);
    assert!(close(&out[0..3], &want, 2), "{:?} vs {want:?}", &out[0..3]);
    assert_eq!(out[3], 255);
    assert!(close(&out[4..7], &[128, 128, 128], 1));
    assert_eq!(out[7], 4); // 1000 / 65535 * 255
    // Identity: plain rounding to 8 bit.
    let id = ToSrgb::new(&ColorTag::default());
    assert_eq!(
        id.rgba16_to_rgba8(&[0, 257, 65535, 32768]).unwrap(),
        [0, 1, 255, 128]
    );
}

#[test]
fn gray_profile() {
    let icc = ColorProfile::new_gray_with_gamma(2.2).encode().unwrap();
    let tag = sniff_bytes(&png_with(Some(&icc), false));
    let t = ToSrgb::new(&tag);
    assert!(t.is_gray(), "{t:?}");
    let out = t
        .gray_alpha8_to_rgba8(&[0, 255, 255, 10, 128, 200])
        .unwrap();
    assert_eq!(&out[0..4], &[0, 0, 0, 255]);
    assert!(close(&out[4..7], &[255, 255, 255], 1));
    assert_eq!(out[7], 10);
    // Gamma 2.2 vs the sRGB curve: mid gray stays neutral, close to 128.
    assert_eq!(out[8], out[9]);
    assert_eq!(out[9], out[10]);
    assert!(out[8].abs_diff(128) <= 6, "{:?}", &out[8..12]);
    assert_eq!(out[11], 200);
    let out16 = t.gray_alpha16_to_rgba8(&[65535, 65535]).unwrap();
    assert!(close(&out16, &[255, 255, 255, 255], 1));
}

#[test]
fn cicp_chunk() {
    let base = png_with(None, false);
    let p3 = sniff_bytes(&insert_chunk(&base, *b"cICP", &[12, 13, 0, 1]));
    assert_eq!(
        p3.cicp,
        Some(Cicp {
            primaries: 12,
            transfer: 13,
            matrix: 0,
            full_range: true
        })
    );
    let t = ToSrgb::new(&p3);
    assert_eq!(t.label(), "Display P3");
    let mut px = vec![200, 100, 50, 255];
    t.rgba8(&mut px).unwrap();
    assert!(close(&px[0..3], &p3_to_srgb_reference([200, 100, 50]), 2));
    // sRGB code points: identity.
    let s = sniff_bytes(&insert_chunk(&base, *b"cICP", &[1, 13, 0, 1]));
    assert!(ToSrgb::new(&s).is_identity());
    // HDR (PQ) is not tone-mapped: sRGB with a note…
    let pq = sniff_bytes(&insert_chunk(&base, *b"cICP", &[9, 16, 0, 1]));
    let t = ToSrgb::new(&pq);
    assert!(t.is_identity());
    assert!(t.note().unwrap().contains("HDR"), "{t:?}");
    // …unless an iCCP fallback is there (cICP first, then iCCP).
    let both = insert_chunk(&png_with(Some(&p3_icc()), false), *b"cICP", &[9, 16, 0, 1]);
    let t = ToSrgb::new(&sniff_bytes(&both));
    assert!(!t.is_identity());
    assert_eq!(t.label(), "Display P3");
    assert!(t.note().is_some());
}

#[test]
fn broken_profiles_fall_back_with_note() {
    let bad = sniff_bytes(&png_with(Some(b"definitely not an ICC profile"), false));
    let t = ToSrgb::new(&bad);
    assert!(t.is_identity());
    assert!(t.note().unwrap().contains("cannot be read"), "{t:?}");
    // Corrupt zlib data inside iCCP.
    let base = png_with(None, false);
    let broken = sniff_bytes(&insert_chunk(&base, *b"iCCP", b"P3\0\0garbage"));
    assert!(broken.error.is_some());
    assert!(
        ToSrgb::new(&broken)
            .note()
            .unwrap()
            .contains("treated as sRGB")
    );
}

#[test]
fn jpeg_icc_and_cmyk() {
    let icc = p3_icc();
    let tag = sniff_bytes(&jpeg_header(Some(&icc), 3));
    assert_eq!(tag.kind, ImageKind::Jpeg);
    assert_eq!(tag.icc.as_deref(), Some(&icc[..]));
    assert!(!tag.cmyk);
    assert_eq!(ToSrgb::new(&tag).label(), "Display P3");
    let plain = sniff_bytes(&jpeg_header(None, 3));
    assert!(plain.is_untagged());
    let cmyk = sniff_bytes(&jpeg_header(None, 4));
    assert!(cmyk.cmyk);
    let t = ToSrgb::new(&cmyk);
    assert!(t.is_identity());
    assert!(t.note().unwrap().contains("CMYK"));
    // A missing APP2 segment is reported.
    let mut one = jpeg_header(Some(&icc), 3);
    let pos = one.windows(2).position(|w| w == [0xFF, 0xE2]).unwrap();
    let len = usize::from(u16::from_be_bytes([one[pos + 2], one[pos + 3]]));
    one.drain(pos..pos + 2 + len);
    let tag = sniff_bytes(&one);
    assert!(tag.icc.is_none());
    assert!(tag.error.unwrap().contains("incomplete"));
}

#[test]
fn other_formats_are_untagged() {
    assert!(sniff_bytes(b"<svg/>").is_untagged());
    assert!(sniff_bytes(&[]).is_untagged());
}

#[test]
fn inspect_file_reports_only_problems() {
    let dir = tempfile::tempdir().unwrap();
    let ok = dir.path().join("p3.png");
    std::fs::write(&ok, png_with(Some(&p3_icc()), false)).unwrap();
    let bad = dir.path().join("bad.png");
    std::fs::write(&bad, png_with(Some(b"nope"), false)).unwrap();
    assert_eq!(inspect_file(&ok), None);
    assert!(inspect_file(&bad).is_some());
    assert_eq!(inspect_file(&dir.path().join("missing.png")), None);
}
